package com.spms.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;import java.util.*;@Entity @Getter @Setter @NoArgsConstructor public class EmployeeDocument{public enum Type{PHOTO,CERTIFICATE}@Id @GeneratedValue private UUID id;@ManyToOne(optional=false)private Employee employee;@Enumerated(EnumType.STRING)private Type documentType;private String title;private String issuer;private LocalDate issueDate;@Column(unique=true)private String objectKey;private String originalName;private String mimeType;private long sizeBytes;@ManyToOne private UserAccount uploadedBy;private LocalDateTime createdAt=LocalDateTime.now();}